bool reap_task_mm(struct task_struct *tsk, struct mm_struct *mm) {
    bool success = false;
    down_read(&mm->mmap_lock);

    if (atomic_read(&mm->mm_users) == 0) {
        up_read(&mm->mmap_lock);
        return false;
    }

    if (test_bit(MMF_OOM_SKIP, &mm->flags)) {
        up_read(&mm->mmap_lock);
        return false;
    }

    set_bit(MMF_OOM_SKIP, &mm->flags);

    struct vm_area_struct *vma, *tmp;
    for (vma = mm->mmap; vma; vma = tmp) {
        tmp = vma->vm_next;
        if (vma->vm_flags & (VM_ANON | VM_SHARED)) {
            do_munmap(mm, vma->vm_start, vma->vm_end - vma->vm_start, 0);
        }
    }

    clear_bit(MMF_OOM_SKIP, &mm->flags);
    up_read(&mm->mmap_lock);
    success = true;
    return success;
}

bool reap_task_mm(struct task_struct *tsk, struct mm_struct *mm) {
    bool success = false;
    down_read(&mm->mmap_lock);

    if (!atomic_read(&mm->notify_count) && !test_bit(MMF_OOM_SKIP, &mm->flags)) {
        set_bit(MMF_UNSTABLE, &mm->flags);

        struct vm_area_struct *vma, *next_vma;
        for (vma = mm->mmap; vma; vma = next_vma) {
            next_vma = vma->vm_next;

            if ((vma->vm_flags & (VM_ANON | VM_SHARED)) == VM_ANON) {
                do_munmap(mm, vma->vm_start, vma->vm_end - vma->vm_start, 0);
            }
        }

        success = true;
        printk(KERN_INFO "Memory reaping completed for task %d\n", tsk->pid);
    }

    up_read(&mm->mmap_lock);
    return success;
}

bool reap_task_mm(struct task_struct *tsk, struct mm_struct *mm)
{
    bool success = false;

    task_lock(tsk);
    if (down_read_trylock(&mm->mmap_lock)) {
        if (!atomic_read(&mm->oom_notifiers_count) && !test_bit(MMF_OOM_SKIP, &mm->flags)) {
            set_bit(MMF_OOM_UNSTABLE, &mm->flags);
            struct vm_area_struct *vma;
            for (vma = mm->mmap; vma; vma = vma->vm_next) {
                if (vma->vm_flags & (VM_ANON | VM_SHARED)) {
                    do_munmap(mm, vma->vm_start, vma->vm_end - vma->vm_start, 0);
                }
            }
            success = true;
        }
        up_read(&mm->mmap_lock);
    }
    task_unlock(tsk);

    return success;
}

bool reap_task_mm(struct task_struct *tsk, struct mm_struct *mm) {
    bool success = false;

    down_read(&mm->mmap_lock);

    if (atomic_read(&mm->_notifier_count) > 0) {
        up_read(&mm->mmap_lock);
        return false;
    }

    if (test_bit(MMF_OOM_SKIP, &mm->flags)) {
        up_read(&mm->mmap_lock);
        return false;
    }

    set_bit(MMF_UNSTABLE, &mm->flags);

    struct vm_area_struct *vma, *next;
    for (vma = mm->mmap; vma != NULL; vma = next) {
        next = vma->vm_next;
        if (vma->vm_flags & (VM_ANON | VM_SHARED)) {
            do_munmap(mm, vma->vm_start, vma->vm_end - vma->vm_start, 0);
        }
    }

    success = true;
    clear_bit(MMF_UNSTABLE, &mm->flags);
    up_read(&mm->mmap_lock);

    return success;
}
